  const sources = parseJson(readBoundedFile(ROOT, KNOWLEDGE + '/sources.lock.json'));
  need(catalog.schemaVersion === '1.0.0' && sources.schemaVersion === '1.0.0', 'INVALID_INPUT', 'Unknown catalog format.');
